{
  "batch": 0,
  "condition": "witness_joint",
  "programs": [
    {
      "features": [],
      "name": "cheap_displacement_density",
      "rationale": "Balances blocked contact count and blocked reward relative to root reward. No additional graph computation is required; this pointwise candidate cannot represent the certified structural reversal.",
      "rule": "weight / (1 + 0.5 * degree + 0.5 * conflict_weight / (1 + weight))"
    },
    {
      "features": [],
      "name": "cheap_gap_aware_regret",
      "rationale": "Uses strongest-neighbor regret for tiny neighborhoods and a smoother crowding penalty otherwise, scaled by actual gap-to-duration cost. It adds no features but remains blind to remote interactions.",
      "rule": "(weight - max_conflict_weight if degree <= 1 else weight / (1 + 0.25 * degree) - 0.25 * conflict_weight / (1 + degree)) / (1 + (station_gap + satellite_gap) / (1 + duration))"
    },
    {
      "features": [
        {
          "expression": {
            "args": [
              {
                "args": [
                  {
                    "args": [
                      {
                        "args": [
                          {
                            "args": [],
                            "op": "root"
                          }
                        ],
                        "op": "neighbors"
                      },
                      {
                        "args": [],
                        "op": "available"
                      }
                    ],
                    "op": "intersection"
                  }
                ],
                "op": "induced_edges"
              }
            ],
            "op": "edge_min_weight_sum"
          },
          "name": "neighbor_edge_mass"
        }
      ],
      "name": "local_redundancy_discount",
      "rationale": "Discounts redundant blocked reward when competing neighbors conflict with one another, retaining a strongest-neighbor floor. Active one-hop edge enumeration can be quadratic in degree and cannot resolve the saved remote witness.",
      "rule": "weight / (1 + max(max_conflict_weight, conflict_weight - 2 * neighbor_edge_mass / max(1, degree)) / (1 + weight))"
    },
    {
      "features": [
        {
          "expression": {
            "args": [
              {
                "args": [
                  {
                    "args": [
                      {
                        "args": [],
                        "op": "root"
                      }
                    ],
                    "op": "neighbors"
                  },
                  {
                    "args": [],
                    "op": "available"
                  }
                ],
                "op": "intersection"
              }
            ],
            "op": "greedy_independent_weight"
          },
          "name": "neighbor_greedy"
        }
      ],
      "name": "local_greedy_exchange",
      "rationale": "Estimates independently packable neighbor reward and scores a normalized exchange margin with a small crowding term. Reach is one hop; repeated greedy computations can be costly in dense neighborhoods.",
      "rule": "(weight - neighbor_greedy) / (1 + weight + neighbor_greedy) + 0.1 * weight / (1 + weight + conflict_weight)"
    },
    {
      "features": [
        {
          "expression": {
            "args": [
              {
                "args": [
                  {
                    "args": [
                      {
                        "args": [],
                        "op": "root"
                      }
                    ],
                    "op": "neighbors"
                  },
                  {
                    "args": [],
                    "op": "available"
                  }
                ],
                "op": "intersection"
              }
            ],
            "op": "greedy_independent_weight"
          },
          "name": "neighbor_greedy"
        },
        {
          "expression": {
            "args": [
              {
                "args": [
                  {
                    "args": [
                      {
                        "args": [],
                        "op": "root"
                      }
                    ],
                    "op": "neighbors"
                  },
                  {
                    "args": [],
                    "op": "available"
                  }
                ],
                "op": "intersection"
              }
            ],
            "op": "clique_cover_weight"
          },
          "name": "neighbor_cover"
        }
      ],
      "name": "local_exchange_confidence",
      "rationale": "Prioritizes roots whose reward covers the neighbor independent-set upper bound; otherwise it uses greedy exchange value with an uncertainty penalty. Both computations remain local, may be expensive, and do not capture the witnessed distant changes.",
      "rule": "1 + (weight - neighbor_cover) / (1 + weight + neighbor_cover) if weight >= neighbor_cover else (weight - neighbor_greedy - 0.25 * max(0, neighbor_cover - neighbor_greedy)) / (1 + weight + neighbor_cover)"
    },
    {
      "features": [
        {
          "expression": {
            "args": [
              {
                "args": [
                  {
                    "args": [],
                    "op": "available"
                  },
                  {
                    "args": [
                      {
                        "args": [
