                          }
                        ],
                        "op": "neighbors"
                      },
                      {
                        "args": [
                          {
                            "args": [],
                            "op": "root"
                          }
                        ],
                        "op": "singleton"
                      }
                    ],
                    "op": "union"
                  }
                ],
                "op": "difference"
              }
            ],
            "op": "greedy_independent_weight"
          },
          "name": "take_greedy"
        },
        {
          "expression": {
            "args": [
              {
                "args": [
