                    "op": "singleton"
                  }
                ],
                "op": "difference"
              }
            ],
            "op": "greedy_independent_weight"
          },
          "name": "skip_greedy"
        }
      ],
      "name": "global_greedy_marginal",
      "rationale": "Compares greedy root-included and root-excluded completion estimates using a root-scale normalized margin. This reaches remote residual structure; two global greedy computations per candidate may dominate total CPU, and their difference is approximate.",
      "rule": "(weight + take_greedy - skip_greedy) / (1 + weight + conflict_weight / (1 + degree)) + 0.05 * weight / (1 + weight + conflict_weight)"
    },
    {
      "features": [
        {
          "expression": {
            "args": [
              {
                "args": [
                  {
                    "args": [],
                    "op": "available"
                  },
                  {
