              }
            ],
            "op": "greedy_independent_weight"
          },
          "name": "residual_greedy"
        },
        {
          "expression": {
            "args": [
              {
                "args": [
                  {
                    "args": [],
                    "op": "available"
                  },
                  {
                    "args": [
                      {
                        "args": [
                          {
                            "args": [],
                            "op": "root"
                          }
                        ],
                        "op": "neighbors"
                      },
                      {
                        "args": [
                          {
