                          }
                        ],
                        "op": "singleton"
                      }
                    ],
                    "op": "union"
                  }
                ],
                "op": "difference"
              }
            ],
            "op": "clique_cover_weight"
          },
          "name": "residual_cover"
        }
      ],
      "name": "global_completion_bound_blend",
      "rationale": "Ranks root-included completions using mostly greedy reward, limited optimism from cover slack, and a mean-conflict penalty. Reach is global; repeated residual greedy and cover computations are expensive, and slack need not predict final schedule quality.",
      "rule": "weight + residual_greedy + 0.2 * max(0, residual_cover - residual_greedy) - 0.1 * conflict_weight / (1 + degree)"
    },
    {
      "features": [
        {
          "expression": {
            "args": [
              {
                "args": [
                  {
                    "args": [
                      {
