                                "args": [],
                                "op": "root"
                              }
                            ],
                            "op": "singleton"
                          }
                        ],
                        "op": "union"
                      }
                    ],
                    "op": "difference"
                  }
                ],
                "op": "induced_edges"
              }
            ],
            "op": "edge_weight_product_sum"
          },
          "name": "residual_edge_product"
        }
      ],
      "name": "global_residual_pressure",
      "rationale": "Approximates retained packing reward from residual edge count and pair-weight pressure, normalizing count and reward scales separately. Global residual edge enumeration may be quadratic, and aggregate pressure can miss arrangement-dependent effects.",
      "rule": "weight + compatible_weight / (1 + residual_edge_count / max(1, remaining_count - degree - 1) + residual_edge_product / (1 + compatible_weight * compatible_weight / max(1, remaining_count - degree - 1)))"
    }
  ],
  "round": 1
}
